CREATE TABLE tlps_pilot_projects(project_id TEXT PRIMARY KEY REFERENCES projects(project_id), enabled_at INTEGER NOT NULL);
CREATE TABLE tlps_pilot_members(project_id TEXT NOT NULL REFERENCES tlps_pilot_projects(project_id), principal_id TEXT NOT NULL REFERENCES principals(principal_id), role TEXT NOT NULL CHECK(role IN ('owner','editor','reviewer','viewer')), active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(project_id,principal_id));
CREATE TABLE tlps_pilot_items(project_id TEXT NOT NULL REFERENCES tlps_pilot_projects(project_id), id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('task','milestone','ticket')), version INTEGER NOT NULL CHECK(version>0), data_json TEXT NOT NULL CHECK(json_valid(data_json)), created_by TEXT NOT NULL REFERENCES principals(principal_id), updated_at INTEGER NOT NULL, PRIMARY KEY(project_id,id));
CREATE TABLE tlps_pilot_reviews(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES tlps_pilot_projects(project_id), profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('approved','returned')), note TEXT NOT NULL, actor TEXT NOT NULL REFERENCES principals(principal_id), recorded_at INTEGER NOT NULL, UNIQUE(project_id,profile_id,profile_version,decision));
CREATE TABLE tlps_pilot_audit(sequence INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES tlps_pilot_projects(project_id),actor TEXT NOT NULL,action TEXT NOT NULL,details_json TEXT NOT NULL CHECK(json_valid(details_json)),recorded_at INTEGER NOT NULL);
CREATE TRIGGER tlps_pilot_audit_no_update BEFORE UPDATE ON tlps_pilot_audit BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER tlps_pilot_audit_no_delete BEFORE DELETE ON tlps_pilot_audit BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER tlps_pilot_reviews_no_update BEFORE UPDATE ON tlps_pilot_reviews BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER tlps_pilot_reviews_no_delete BEFORE DELETE ON tlps_pilot_reviews BEGIN SELECT RAISE(ABORT,'append only'); END;
